import subprocess
from pathlib import Path
root = Path(r"C:\Users\acer\OneDrive\Desktop\ConstraintFlip")
for task_dir in sorted((root / "tasks").iterdir()):
    if not task_dir.is_dir():
        continue
    task_id = task_dir.name.split("_")[0]
    ref_exe = root / "reference" / f"{task_id}.exe"
    if not ref_exe.exists():
        cp = subprocess.run(["g++", "-std=c++17", "-O2", str(root / "reference" / f"{task_id}.cpp"), "-o", str(ref_exe)], capture_output=True, text=True)
        if cp.returncode != 0:
            raise SystemExit(cp.returncode)
    for inp_path in sorted(task_dir.glob("tests/*.in")):
        data = inp_path.read_text(encoding="utf-8")
        got = subprocess.run([str(ref_exe)], input=data, capture_output=True, text=True, check=False)
        expected = inp_path.with_suffix(".out").read_text(encoding="utf-8")
        if got.returncode != 0 or got.stdout.strip() != expected.strip():
            raise SystemExit(f"{task_id} public test failed: {inp_path.name}")
